package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;

/** Actual report conflict retention SQL; worker admission/reference ports and Sender are fictional. */
@EnabledIfEnvironmentVariable(named="B44_MYSQL",matches="true")
class OwnerJobDiscardResultMySqlTest {
    ResultJdbcStoreTest f;OwnerJobDiscardResultService service;long revision;
    final IdentityService.Actor owner=new IdentityService.Actor("fictional-owner","owner");
    @BeforeEach void setup(){f=new ResultJdbcMySqlTest();f.fixture();f.existingContent();assertEquals(ResultApplicationService.Status.CONTENT_REVISION_CONFLICT,f.apply().status());revision=new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).revision();service=new OwnerJobDiscardResultService(f.writes,new JdbcOwnerResultDiscard(f.source),new JdbcFrozenInputs(f.source),f.clock);}
    JdbcOwnerResultDiscard.Discarded discard(String key){return service.discard(owner,ResultJdbcStoreTest.ROOT,revision,"Fictional retained result abandonment",key);}
    @Test void discardKeepsContentOriginalResultInputAttemptSlotAndUsedBudget(){var before=new JdbcJobRecords(f.source).byId(f.identity.attemptId());String content=f.jdbc.queryForObject("SELECT body_json FROM contents WHERE id='fictional-report'",String.class),input=new JdbcFrozenInputs(f.source).read(ResultJdbcStoreTest.ROOT,f.identity.inputHash()),result=new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).resultHash();f.jdbc.update("UPDATE worker_lock SET slot_state='occupied',job_id='fictional-new-attempt',holder='fictional-new-worker',slot_revision=slot_revision+1,fencing_token=fencing_token+1");var slot=new JdbcWorkerState(f.source).slot();var effect=discard("fictional-discard!");assertEquals(revision+1,effect.revision());assertEquals(result,effect.resultHash());assertEquals("discarded",new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).state());assertEquals("DISCARDED",new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).application());assertEquals(before,new JdbcJobRecords(f.source).byId(f.identity.attemptId()));assertEquals(slot,new JdbcWorkerState(f.source).slot());assertEquals(content,f.jdbc.queryForObject("SELECT body_json FROM contents WHERE id='fictional-report'",String.class));assertEquals(input,new JdbcFrozenInputs(f.source).read(ResultJdbcStoreTest.ROOT,f.identity.inputHash()));assertEquals(1,new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).callCount());assertEquals(1,f.sends);assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE purpose='result'",Integer.class));}
    @Test void originalEffectReplaysAfterRevisionChangeAndExactCommandRebindingFails(){var first=discard("fictional-discard-replay");f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",ResultJdbcStoreTest.ROOT);assertEquals(first,discard("fictional-discard-replay"));assertEquals("identity_conflict",assertThrows(JdbcOwnerResultDiscard.Rejected.class,()->service.discard(owner,ResultJdbcStoreTest.ROOT,revision,"Fictional changed reason","fictional-discard-replay")).getMessage());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_discard_result'",Integer.class));}
    @Test void roleMissingRootAndWrongRevisionRefuseBeforeChangingAnything(){assertThrows(IdentityService.Rejected.class,()->service.discard(new IdentityService.Actor("fictional-member","member"),ResultJdbcStoreTest.ROOT,revision,"Fictional role","fictional-role"));assertEquals("not_found",assertThrows(JdbcOwnerResultDiscard.Rejected.class,()->service.discard(owner,"fictional-absent",0,"Fictional missing","fictional-missing")).getMessage());assertEquals("revision_conflict",assertThrows(JdbcOwnerResultDiscard.Rejected.class,()->service.discard(owner,ResultJdbcStoreTest.ROOT,revision+1,"Fictional stale","fictional-stale")).getMessage());assertEquals("result_conflict",new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).state());}
    @Test void runningUnknownOrAlreadyAppliedRootsCannotDiscard(){for(String state:new String[]{"running","unknown_external","succeeded"}){f.jdbc.update("UPDATE jobs SET state=? WHERE id=?",state,ResultJdbcStoreTest.ROOT);assertEquals("run_frozen",assertThrows(JdbcOwnerResultDiscard.Rejected.class,()->discard("fictional-state-"+state)).getMessage());}f.jdbc.update("UPDATE jobs SET state='result_conflict',applied_at=? WHERE id=?",java.sql.Timestamp.from(f.clock.instant()),ResultJdbcStoreTest.ROOT);assertThrows(JdbcOwnerResultDiscard.Rejected.class,()->discard("fictional-applied"));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_discard_result'",Integer.class));}
    @Test void originalRetainedOrClaimDamageRefusesWithoutDiscard(){String raw=f.jdbc.queryForObject("SELECT payload_json FROM jobs WHERE purpose='result'",String.class);f.jdbc.update("UPDATE jobs SET payload_json=? WHERE purpose='result'",raw.replace("Fictional text","Fictional altered"));assertThrows(RuntimeException.class,()->discard("fictional-result-damage"));f.jdbc.update("UPDATE jobs SET payload_json=? WHERE purpose='result'",raw);f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='worker_claim'",new byte[32]);assertThrows(RuntimeException.class,()->discard("fictional-claim-damage"));assertEquals(revision,new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).revision());}
    @Test void failedDispositionRollsBackAndAcknowledgementLossRecoversOneOriginalEffect(){f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_discard_receipt CHECK(target_type IS NULL OR target_type<>'job_discard_result')");assertThrows(RuntimeException.class,()->discard("fictional-receipt-failure"));assertEquals(revision,new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).revision());assertEquals("result_conflict",new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).state());f.jdbc.execute("ALTER TABLE jobs DROP CHECK fictional_discard_receipt");f.tx.ackLost=true;var effect=discard("fictional-ack-loss");assertEquals(effect,discard("fictional-ack-loss"));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_discard_result'",Integer.class));}
    @Test void damagedOriginalDispositionCannotBeReplayed(){discard("fictional-receipt-damage");f.jdbc.update("UPDATE jobs SET target_key_hash=? WHERE target_type='job_discard_result'",new byte[32]);assertThrows(JdbcOwnerResultDiscard.Rejected.class,()->discard("fictional-receipt-damage"));assertEquals(revision+1,new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).revision());}
    @Test void damagedOriginalInputPartRefusesBeforeChangingRoot(){f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE owner_job_id=? AND purpose='input' AND part_no=0",new byte[32],ResultJdbcStoreTest.ROOT);assertThrows(RuntimeException.class,()->discard("fictional-input-damage"));assertEquals(revision,new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).revision());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_discard_result'",Integer.class));}
    @Test void oversizedAttemptManifestAndUnexpectedAttemptPayloadRefuseBoundedProof(){f.jdbc.update("UPDATE jobs SET result_json=? WHERE id=?","{\"fictional\":\""+"x".repeat(20000)+"\"}",f.identity.attemptId());assertThrows(RuntimeException.class,()->discard("fictional-oversized-manifest"));f.jdbc.update("UPDATE jobs SET result_json=(SELECT value FROM (SELECT result_json AS value FROM jobs WHERE id=?) original),payload_json=? WHERE id=?",ResultJdbcStoreTest.ROOT,"{\"fictional\":\"unexpected\"}",f.identity.attemptId());assertThrows(RuntimeException.class,()->discard("fictional-unexpected-payload"));assertEquals(revision,new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).revision());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_discard_result'",Integer.class));}
}
